+<!doctype html>
+<html lang="en">
+<head>
+    <meta charset="utf-8" />
+    <meta name="viewport" content="width=device-width, initial-scale=1" />
+    <title>@title · Umbraco Bench</title>
+    <meta name="description" content="Field notes about Model Context Protocol, built in Umbraco with blocks." />
+    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
+</head>
+<body class="min-h-screen bg-stone-950 text-stone-100 antialiased">
+    <header class="border-b border-white/10">
+        <div class="mx-auto flex max-w-6xl items-center justify-between px-6 py-5 lg:px-8">
+            <a class="text-sm font-semibold tracking-[0.2em] text-white uppercase" href="/">MCP Field Notes</a>
+            <span class="text-xs text-stone-400">Built with Umbraco + MCP</span>
+        </div>
+    </header>
+    <main>
+        @RenderBody()
+    </main>
+    <footer class="mt-20 border-t border-white/10">
+        <div class="mx-auto max-w-6xl px-6 py-8 text-sm text-stone-500 lg:px-8">
+            Structured content, rendered through Umbraco's Block Grid pipeline.
+        </div>
+    </footer>
+    <script type="module" src="~/dist/main.js" asp-append-version="true"></script>
+</body>
+</html>

