@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Bench.Umbraco.Models.Blocks
@using Umbraco.Cms.Core.Models.Blocks
@inherits UmbracoViewPage<BlockGridItem<ArticleHeaderBlock>>
@{
    var model = new ArticleHeaderModel
    {
        Heading = Model.Content.Heading ?? string.Empty,
        Summary = Model.Content.Summary ?? string.Empty,
        PublishedDate = Model.Content.PublishedDate,
        ImageUrl = Model.Content.Image?.GetCropUrl(width: 1600, height: 900) ?? string.Empty,
        ImageAlt = Model.Content.ImageAlt ?? string.Empty,
        ImageCredit = Model.Content.ImageCredit ?? string.Empty
    };
}
