diff --git a/Umbraco.Bench.Umbraco/Views/Partials/blockgrid/Components/postListingBlock.cshtml b/Umbraco.Bench.Umbraco/Views/Partials/blockgrid/Components/postListingBlock.cshtml
new file mode 100644
index 0000000000000000000000000000000000000000..95e7917007d9fb49bdb9035ff1a5753f93e10063
--- /dev/null
+++ b/Umbraco.Bench.Umbraco/Views/Partials/blockgrid/Components/postListingBlock.cshtml
@@ -0,0 +1,28 @@
+@using Umbraco.Bench.Umbraco.Models
+@using Umbraco.Bench.Umbraco.Models.Blocks
+@using Umbraco.Cms.Core.Models.Blocks
+@inherits UmbracoViewPage<BlockGridItem<PostListingBlock>>
+@{
+    var page = UmbracoContext.PublishedRequest?.PublishedContent;
+    var posts = page?.Children<BlogPost>()
+        .Select(post => new
+        {
+            Post = post,
+            Header = post.Blocks?.Select(item => item.Content).OfType<ArticleHeaderBlock>().FirstOrDefault()
+        })
+        .Where(item => item.Header is not null)
+        .OrderByDescending(item => item.Header!.PublishedDate)
+        .Select(item => new PostCardModel
+        {
+            Heading = item.Header!.Heading ?? item.Post.Name,
+            Summary = item.Header.Summary ?? string.Empty,
+            PublishedDate = item.Header.PublishedDate,
+            ImageUrl = item.Header.Image?.GetCropUrl(width: 900, height: 600) ?? string.Empty,
+            ImageAlt = item.Header.ImageAlt ?? string.Empty,
+            Url = item.Post.Url()
+        })
+        .ToList() ?? [];
+
+    var model = new PostListingModel { Posts = posts };
+}
+@await Component.InvokeAsync("PostListing", new { model })
